"MCP (Model Context Protocol) is an open standard for connecting AI apps to the tools and data they use. A server describes what it can do. The AI app shows that to the model. When the model wants to use something, the app calls the server and hands the result back. One protocol, so any app can work with any server.": "MCP（Model Context Protocol）是一个开放标准，用来把 AI 应用连接到它们所用的工具和数据。服务器描述自己能做什么，AI 应用把这些信息展示给模型。当模型想使用某个能力时，应用就去调用服务器，并把结果交还给模型。协议只有一套，所以任何应用都能和任何服务器配合使用。",
"In one line": "一句话概括",
"a standard plug between AI apps and the tools and data they use": "AI 应用与其所用工具和数据之间的标准插头",
