"no: JSON-RPC messages over stdin/stdout or one HTTP endpoint, and the server can send messages too": "不是：JSON-RPC 消息走 stdin/stdout 或单个 HTTP 端点，而且服务器也能主动发消息",
"Just JSON-RPC?": "只是 JSON-RPC 吗？",
"JSON-RPC is only the envelope; MCP defines the methods (tools/list, tools/call…), capability negotiation, transports and OAuth": "JSON-RPC 只是信封；MCP 定义了方法（tools/list、tools/call…）、能力协商、传输方式和 OAuth",
"Why not a CLI?": "为什么不用 CLI？",
"coding agents with a shell often do fine with CLIs; MCP fits agents without a shell, remote servers with per-user auth, and narrow, auditable access": "带 shell 的编码 agent 用 CLI 往往就够了；MCP 适合没有 shell 的 agent、需要按用户鉴权的远程服务器，以及范围收窄、可审计的访问",
