"github-mcp": "github-mcp",
"host app": "宿主应用",
"Request": "请求",
"Asks for something and expects exactly one response with the same id.": "请求某项内容，并期望收到恰好一个带相同 id 的响应。",
"id 1 · list the tools": "id 1 · 列出工具",
"id": "id",
"String or integer, never null. Not reused by the sender within the session.": "字符串或整数，不能为 null。发送方在会话内不会重复使用。",
"method": "method",
"What to do. MCP defines the method names.": "要做什么。方法名由 MCP 定义。",
