"error.code": "error.code",
"Standard JSON-RPC codes. MCP adds a few, e.g. -32002 resource not found, -32042 URL elicitation required.": "标准 JSON-RPC 错误码。MCP 又增加了几个，例如 -32002 资源未找到、-32042 需要 URL 征询。",
"error.data": "error.data",
"Optional extra detail.": "可选的额外细节。",
"Notification": "通知",
"No id means fire and forget. Here the server tells the client its tool list changed.": "没有 id 就是发后即忘。这里是服务器告诉客户端它的工具列表变了。",
"tools changed, no reply expected": "工具已变化，无需回复",
"(no id)": "（无 id）",
