"All MCP notifications live under this prefix.": "所有 MCP 通知都使用这个前缀。",
"Batch": "批处理",
"JSON-RPC batching came in with 2025-03-26 and was removed in 2025-06-18. Send separate messages instead; several can still be in flight at once.": "JSON-RPC 批处理在 2025-03-26 引入，并在 2025-06-18 移除。请改为发送单独的消息；仍然可以同时有多条消息在途。",
"An array of messages in one frame. Shown so you recognise it in old logs.": "一帧中包含一个消息数组。展示出来是为了让你在旧日志里能认出它。",
"array of 2 requests": "2 个请求的数组",
"A JSON array instead of one object. Only valid in 2025-03-26.": "用一个 JSON 数组代替单个对象。仅在 2025-03-26 中有效。",
"array of 2 responses": "2 个响应的数组",
"Base protocol": "基础协议",
"JSON-RPC 2.0": "JSON-RPC 2.0",
"schema.ts": "schema.ts",
"Every result carries a required resultType: \"complete\" or \"input_required\".": "每个结果都带有必需的 resultType：\"complete\" 或 \"input_required\"。",
"Servers no longer send requests to clients: they return input_required and the client retries with the answers (multi round-trip).": "服务器不再向客户端发送请求：它们返回 input_required，客户端带着答案重试（多轮往返）。",
"Resource not found moves from -32002 to -32602; new MCP codes -32020 to -32022.": "资源未找到从 -32002 改为 -32602；新增 MCP 错误码 -32020 到 -32022。",
"Still JSON-RPC 2.0, but tighter. Only the client sends requests; the server answers, notifies, or returns resultType \"input_required\" to ask for more. Every result says its resultType, and every request carries its protocol version and client capabilities in _meta, since there is no initialize handshake.": "仍然是 JSON-RPC 2.0，但更严格。只有客户端发送请求；服务器负责响应、发通知，或返回 resultType \"input_required\" 来索取更多信息。每个结果都会标明 resultType，每个请求都在 _meta 中携带协议版本和客户端能力，因为不再有 initialize 握手。",
"requests client → server only; servers send results and notifications": "请求只能从客户端发往服务器；服务器发送结果和通知",
"resultType": "resultType",
"required on every result: complete or input_required": "每个结果都必须带：complete 或 input_required",
"Request _meta": "请求 _meta",
"io.modelcontextprotocol/protocolVersion + clientCapabilities (required)": "io.modelcontextprotocol/protocolVersion + clientCapabilities（必需）",
"JSON-RPC set; -32000…-32019 implementation-defined; -32020…-32099 MCP": "JSON-RPC 标准码；-32000…-32019 由实现自定义；-32020…-32099 属于 MCP",
"Resource not found": "资源未找到",
"-32602 (was -32002)": "-32602（原为 -32002）",
"batching (2025-06-18); ping, server → client requests (2026-07-28)": "批处理（2025-06-18）；ping、服务器 → 客户端请求（2026-07-28）",
"MCP spec 2026-07-28, Base protocol": "MCP 规范 2026-07-28，基础协议",
"Asks for something and expects exactly one response with the same id. With no initialize, the request itself says which version and capabilities apply.": "请求某项内容，并期望收到恰好一个带相同 id 的响应。没有 initialize，请求本身就说明适用哪个版本和哪些能力。",
"String or integer, never null. A retry is a new request with a new id.": "字符串或整数，不能为 null。重试是一个带新 id 的新请求。",
"_meta protocolVersion": "_meta protocolVersion",
"Required on every request. Over HTTP it must match the MCP-Protocol-Version header.": "每个请求都必需。通过 HTTP 时，必须与 MCP-Protocol-Version 请求头一致。",
"_meta clientCapabilities": "_meta clientCapabilities",
"Declared per request. Servers must not infer them from earlier requests.": "按请求声明。服务器不得根据之前的请求去推断。",
"The server answers id 1. resultType tells the client how to read the result.": "服务器回答 id 1。resultType 告诉客户端该如何解读结果。",
"id 1 · complete · 1 tool": "id 1 · complete · 1 个工具",
"\"complete\" for a final result. A client treats a missing resultType from an older server as complete.": "\"complete\" 表示最终结果。客户端会把旧版服务器缺失的 resultType 视为 complete。",
"ttlMs, cacheScope": "ttlMs, cacheScope",
"List and read results say how long they may be cached and by whom.": "列表和读取结果会说明可以缓存多久、由谁缓存。",
"Input required": "需要输入",
"The other result type. Instead of sending its own request, the server answers with what it still needs. The client gathers it and retries.": "另一种结果类型。服务器不再自己发送请求，而是回答它还需要什么。客户端收集后重试。",
"id 2 · deploy": "id 2 · deploy",
"id 2 · input_required": "id 2 · input_required",
"inputRequests": "inputRequests",
"Requests the server would once have sent itself (elicitation, sampling, roots), keyed by name.": "服务器原本会自己发出的请求（征询、采样、根目录），以名称为键。",
"requestState": "requestState",
"Opaque. The client echoes it on the retry. See Sampling, Elicitation, Roots.": "不透明数据。客户端在重试时原样回传。参见采样、征询、根目录。",
"id 3 · tools/delete (no such method)": "id 3 · tools/delete（没有这个方法）",
"id 3 · -32601 Method not found": "id 3 · -32601 Method not found",
"MCP's own codes sit in -32020…-32099: -32020 header mismatch, -32021 missing client capability, -32022 unsupported protocol version.": "MCP 自己的错误码位于 -32020…-32099：-32020 请求头不匹配，-32021 缺少客户端能力，-32022 不支持的协议版本。",
"retired": "已停用",
"-32002 (now -32602) and -32042 stay reserved and are never reused.": "-32002（现为 -32602）和 -32042 仍为保留值，永不复用。",
"No id means fire and forget. Change notifications now arrive only on a subscriptions/listen stream the client opened.": "没有 id 就是发后即忘。变更通知现在只会出现在客户端打开的 subscriptions/listen 流上。",
"tools changed (subscription 9)": "工具已变化（订阅 9）",
"subscriptionId": "subscriptionId",
"The id of the subscriptions/listen request this stream belongs to. See Tools.": "该流所属的 subscriptions/listen 请求的 id。参见工具。",
"A JSON array instead of one object. Each request keeps its own id.": "用一个 JSON 数组代替单个对象。每个请求保留各自的 id。",
"Responses come back as an array too, matched by id, in any order.": "响应同样以数组形式返回，按 id 匹配，顺序不限。",
"Every result carries resultType: complete or input_required.": "每个结果都带有 resultType：complete 或 input_required。",
"Servers no longer send requests: they return input_required and the client retries (MRTR). ping is gone.": "服务器不再发送请求：它们返回 input_required，客户端重试（MRTR）。ping 已取消。",
"Each request carries protocolVersion and clientCapabilities in _meta; no initialize.": "每个请求都在 _meta 中携带 protocolVersion 和 clientCapabilities；没有 initialize。",
"Error code policy: -32020…-32099 reserved for MCP. Resource not found -32002 → -32602.": "错误码策略：-32020…-32099 保留给 MCP。资源未找到 -32002 → -32602。",
"MCP spec 2025-06-18, Base protocol": "MCP 规范 2025-06-18，基础协议",
"Standard JSON-RPC codes. MCP adds -32002 resource not found.": "标准 JSON-RPC 错误码。MCP 增加了 -32002 资源未找到。",
"JSON-RPC batching came in with 2025-03-26 and is removed in this version. Send separate messages instead; several can still be in flight at once.": "JSON-RPC 批处理在 2025-03-26 引入，并在本版本中移除。请改为发送单独的消息；仍然可以同时有多条消息在途。",
"JSON-RPC batching removed.": "JSON-RPC 批处理已移除。",
