"Batching": "批处理",
"arrays of messages: MAY send, MUST accept (new in 2025-03-26)": "消息数组：可以发送（MAY），必须接受（MUST）（2025-03-26 新增）",
"MCP spec 2025-03-26, Base protocol": "MCP 规范 2025-03-26，基础协议",
"An array of requests and notifications in one frame. Implementations MAY send batches and MUST accept them.": "一帧中包含一个由请求和通知组成的数组。实现可以发送批处理（MAY），并且必须接受（MUST）。",
"JSON-RPC batching added: implementations MAY send arrays and MUST accept them.": "新增 JSON-RPC 批处理：实现可以发送（MAY）数组，并且必须接受（MUST）。",
"Single-message shapes unchanged.": "单消息形态保持不变。",
"MCP spec 2024-11-05, Base protocol": "MCP 规范 2024-11-05，基础协议",
"First dated revision: requests, responses and notifications over JSON-RPC 2.0.": "第一个带日期的版本：基于 JSON-RPC 2.0 的请求、响应和通知。",
"One message per frame; no batching yet.": "每帧一条消息；还没有批处理。",
"Servers can send requests too (sampling, roots).": "服务器也可以发送请求（采样、根目录）。",
"Lifecycle": "生命周期",
"Initialize, operate, shut down": "初始化、运行、关闭",
"A connection starts with a handshake. The client says which protocol version and features it supports, the server answers with its own, and from then on both sides only use what the other declared. Until the handshake is done, the client should only send pings, and the server only pings and log messages.": "连接以握手开始。客户端说明自己支持的协议版本和功能，服务器回复它自己的，此后双方只使用对方声明过的内容。握手完成之前，客户端只应发送 ping，服务器只应发送 ping 和日志消息。",
"Phases": "阶段",
"initialize → operation → shutdown": "initialize → 运行 → 关闭",
"Negotiated": "协商内容",
"protocol version + capabilities": "协议版本 + 能力",
"Client capabilities": "客户端能力",
"roots, sampling, elicitation, tasks, experimental": "roots、sampling、elicitation、tasks、experimental",
"Server capabilities": "服务器能力",
"tools, resources, prompts, logging, completions, tasks, experimental": "tools、resources、prompts、logging、completions、tasks、experimental",
"Keepalive": "保活",
"ping, either side": "ping，任意一方均可",
"Timeouts": "超时",
"per request; on expiry send notifications/cancelled": "按请求计；到期时发送 notifications/cancelled",
"Host app": "宿主应用",
"Claude, Cursor, an agent": "Claude、Cursor、某个 agent",
"Initialize": "初始化",
"The host starts one client per server. The client opens with its version, features and identity.": "宿主为每个服务器启动一个客户端。客户端以自己的版本、功能和身份开场。",
"connect github-mcp": "连接 github-mcp",
"id 0 · version 2025-11-25": "id 0 · 版本 2025-11-25",
"protocolVersion": "protocolVersion",
"The newest version the client speaks.": "客户端所支持的最新版本。",
"capabilities": "capabilities",
