"clientInfo": "clientInfo",
"Name/version, for logs and quirks.": "名称/版本，用于日志和兼容性处理。",
"Negotiate": "协商",
"The server echoes the client's version if it supports it, otherwise offers its own latest, and lists its own features. Optional instructions are a hint the host may add to the system prompt.": "如果支持，服务器会回显客户端的版本，否则给出它自己的最新版本，并列出自己的功能。可选的 instructions 是一条提示，宿主可以把它加入系统提示词。",
"id 0 · tools, resources, prompts": "id 0 · tools、resources、prompts",
