"An open standard for connecting AI apps to the tools and data they use. A server says what it can do, the app shows that to the model, and when the model wants something the app calls the server and hands the result back.": "一个把 AI 应用连接到工具和数据的开放标准。服务器声明自己能做什么，应用把这些告诉模型；模型需要某样东西时，应用去调用服务器，再把结果交回给模型。",
"a small program exposing tools, data or prompts": "一个提供工具、数据或提示词模板的小程序",
"decides what to use; never talks to a server directly": "决定用什么；从不直接和服务器通信",
"Not REST": "不是 REST",
"JSON-RPC over stdin/stdout or one HTTP endpoint, and servers can talk back": "基于 stdin/stdout 或单个 HTTP 端点的 JSON-RPC，服务器也能反过来发消息",
"Not just JSON-RPC": "不只是 JSON-RPC",
"JSON-RPC is the envelope. MCP defines what goes in it: the methods, capability negotiation, transports and auth": "JSON-RPC 只是信封。MCP 规定信封里装什么：方法、能力协商、传输方式和授权",
